    expect(() => validateInput({ tasks: [{ id: "a", duration: -1 }] })).toThrow("non-negative");
    expect(() => validateInput({ tasks: [{ id: "a", duration: 1, dependsOn: ["x"] }] })).toThrow("unknown task");
